<script setup lang="ts">
// Author by Lab | zefry. Business administration is deliberately outside this POS application.
import { computed, onMounted, onUnmounted, ref } from 'vue'
import { invoke } from '@tauri-apps/api/core'
import { listen, type UnlistenFn } from '@tauri-apps/api/event'
import Icon from './Icon.vue'
import EnterprisePanels from './EnterprisePanels.vue'
import type { Product, Line, Receipt, Printer, Workspace, Security, UpdateInfo, Logo } from './types'
const appVersion=ref('…'),checkingUpdate=ref(false),updateStage=ref('check'),updateBytes=ref(0),updateTotal=ref(0);let unlistenUpdate:UnlistenFn|undefined
const language = ref(localStorage.getItem('oneqay.pos.locale') === 'en' ? 'en' : 'id')
const tr = (id:string,en:string) => language.value === 'id' ? id : en
const tab = ref('dashboard'), search = ref(''), category = ref(''), connecting = ref(false), saving = ref(false), syncing = ref(false)
const online = ref(false), lastSync = ref(0), failureCount = ref(0), error = ref(''), notice = ref(''), showConnect = ref(true)
const email = ref(''), password = ref(''), totp = ref(''), pin = ref(''), queues = ref<string[]>([]), cash = ref(''), checkout = ref(false)
const cart = ref<Line[]>([]), counts = ref<Record<string,number>>({}), operationId = ref(''), selectedReceipt = ref<Receipt|null>(null)
const view = ref<Workspace>({shift:null,kitchen_printers:{},kitchen_jobs:[],metrics:{},snapshot:null,products:[],operations:[],settings:{transport:'windows',queue:'',host:'',port:9100,paper_mm:80,drawer_enabled:false,auto_print:false},last_server_at:0,pending:0,review:0,authorized:false,lease_remaining:0})
const security=ref<Security>({signed_in:false,locked:true,login:'',offline:false,updating:false})
const tableNumber=ref(''),orderNumber=ref(''),shiftDialog=ref(false),shiftOpening=ref(true),shiftCash=ref(''),shiftNote=ref(''),shiftOperation=ref(''),patch=ref<UpdateInfo|null>(null),installing=ref(false)
let securityTimer:ReturnType<typeof setInterval>|undefined,updateTimer:ReturnType<typeof setInterval>|undefined,lastActivity=0
const blocked=computed(()=>showConnect.value||security.value.locked||shiftDialog.value||checkout.value||selectedReceipt.value!==null)
const printer = ref<Printer>({...view.value.settings})
const leaseDeadline = ref(0)
const now = ref(Date.now()), barcodeInput = ref<HTMLInputElement|null>(null)
let lastSyncError='';let timer:ReturnType<typeof setTimeout>|undefined, clock:ReturnType<typeof setInterval>|undefined
const currency = computed(()=>view.value.products[0]?.currency??'IDR'), scale = computed(()=>view.value.products[0]?.scale??0)
const money = (amount:number) => view.value.snapshot?.currency_symbol ? `${view.value.snapshot.currency_symbol} ${new Intl.NumberFormat(language.value==='id'?'id-ID':'en-US',{minimumFractionDigits:scale.value,maximumFractionDigits:scale.value}).format(amount/10**scale.value)}` : new Intl.NumberFormat(language.value==='id'?'id-ID':'en-US',{style:'currency',currency:currency.value,maximumFractionDigits:scale.value,minimumFractionDigits:scale.value}).format(amount / 10**scale.value)
const products = computed(()=>view.value.products.filter(p=>(!category.value||p.category===category.value)&&(!search.value||[p.name,p.barcode,p.id].some(x=>x.toLocaleLowerCase().includes(search.value.toLocaleLowerCase())))).slice(0,160))
const categories = computed(()=>[...new Set(view.value.products.map(p=>p.category).filter(Boolean))])
const cartLines = computed(()=>cart.value.map(l=>({...l,product:view.value.products.find(p=>p.id===l.product_id)!})).filter(l=>l.product))
const total = computed(()=>cartLines.value.reduce((sum,l)=>sum+l.product.price*l.quantity,0))
const quantity = computed(()=>cart.value.reduce((sum,l)=>sum+l.quantity,0))
const shiftReady=computed(()=>!view.value.shift_status||view.value.shift_status==='ready')
const leaseExpired = computed(()=>!view.value.authorized||!view.value.snapshot||now.value>leaseDeadline.value)
const cashAtomic = computed(()=>{const raw=cash.value.trim();const pattern=new RegExp(`^\\d+(?:[.,]\\d{1,${Math.max(1,scale.value)}})?$`);if(!pattern.test(raw)||(scale.value===0&&/[.,]/.test(raw)))return -1;const [whole,fraction='']=raw.replace(',','.').split('.');const value=Number(whole)*10**scale.value+Number(fraction.padEnd(scale.value,'0'));return Number.isSafeInteger(value)?value:-1})
const cashValid = computed(()=>cashAtomic.value>=total.value&&total.value>=0&&cart.value.length>0)
const stats = computed(()=>view.value.operations.filter(o=>o.operation.kind==='sale'&&new Date(o.operation.created_at*1000).toDateString()===new Date().toDateString()))
const salesToday = computed(()=>view.value.metrics.gross??0)
const needsLogin = computed(()=>error.value.includes('POS_SIGN_IN_AGAIN'))
const nav = computed(()=>[{id:'dashboard',icon:'layout-dashboard',label:tr('Ringkasan','Overview')},{id:'sale',icon:'shopping-cart',label:tr('Kasir','Checkout')},{id:'history',icon:'receipt-text',label:tr('Transaksi','Transactions')},{id:'sync',icon:'refresh-cw',label:tr('Sinkronisasi','Sync'),badge:view.value.pending+view.value.review},...(view.value.snapshot?.can_count?[{id:'count',icon:'scan-line',label:tr('Opname stok','Stock count')}]:[]),{id:'shifts',icon:'wallet',label:tr('Shift & laporan','Shifts & reports')},{id:'kitchens',icon:'printer',label:tr('Dapur','Kitchens')},{id:'settings',icon:'settings-2',label:tr('Perangkat','Devices')},{id:'updates',icon:'refresh-cw',label:tr('Pembaruan','Updates'),badge:patch.value?.available?1:0}])
function changeLanguage(){language.value=language.value==='id'?'en':'id';localStorage.setItem('oneqay.pos.locale',language.value);document.documentElement.lang=language.value}
function update(workspace:Workspace){view.value=workspace;if(selectedReceipt.value)selectedReceipt.value=workspace.operations.find(o=>o.operation.operation_id===selectedReceipt.value?.operation.operation_id)??selectedReceipt.value;leaseDeadline.value=Date.now()+workspace.lease_remaining*1000}
function humanError(raw:string){if(raw.includes('PIN_INVALID')||raw.includes('LOGIN_INVALID'))return tr('Email, password, atau PIN belum sesuai. Silakan periksa kembali.','Your email, password, or PIN does not match. Please check again.');if(raw.includes('TOO_MANY_ATTEMPTS'))return tr('Terlalu banyak percobaan. Silakan tunggu 5 menit.','Too many attempts. Please wait 5 minutes.');if(raw.includes('UPDATE'))return tr('Pembaruan belum dapat dilanjutkan. Pastikan internet tersambung. Data shift dan antrean transaksi akan dicadangkan sebelum pemasangan.','The update cannot continue yet. Connect to the internet. Shift data and the transaction queue are backed up before installation.');if(raw.includes('NETWORK'))return tr('Koneksi belum tersedia. Transaksi lokal tetap tersimpan.','Connection unavailable. Local transactions are safely stored.');if(raw.includes('SIGN_IN'))return tr('Sesi keamanan berakhir. Silakan masuk kembali dengan akun kasir Anda.','Your security session ended. Please sign in again with your cashier account.');if(raw.includes('LEASE_EXPIRED'))return tr('Batas transaksi offline telah berakhir. Sambungkan internet untuk memperbarui izin.','The offline window has ended. Reconnect to refresh authorization.');if(raw.includes('STOCK'))return tr('Jumlah melebihi stok yang tersedia di perangkat ini.','The quantity exceeds stock available on this device.');if(raw.includes('PRINT'))return tr('Periksa printer dan kertas. Transaksi tetap tersimpan. Periksa hasil cetak sebelum mencetak salinan.','Check the printer and paper. The sale is saved. Check the output before printing a copy.');if(raw.includes('SHIFT'))return tr('Akun sudah terhubung. Periksa informasi shift di menu Shift & laporan sebelum membuka kas berikutnya.','Your account is connected. Check Shift & reports before opening the next register.');return tr('Belum berhasil. Coba lagi atau sampaikan kode berikut kepada tim bantuan.','Unable to complete. Try again or share this code with support.')}
function fail(e:unknown){error.value=String(e);notice.value=''}
function add(p:Product){if(saving.value)return;const old=cart.value.find(l=>l.product_id===p.id);if(p.tracks_stock!==false&&(old?.quantity??0)>=p.stock){fail('POS_LOCAL_STOCK_INSUFFICIENT');return}if(old)old.quantity++;else cart.value.push({product_id:p.id,quantity:1});operationId.value='';}
function adjust(id:string,delta:number){if(saving.value)return;const item=cart.value.find(l=>l.product_id===id);if(!item)return;if(delta>0){const p=view.value.products.find(p=>p.id===id);if(p)add(p);return}item.quantity--;cart.value=cart.value.filter(l=>l.quantity>0);operationId.value=''}
function scan(){const match=view.value.products.find(p=>p.barcode===search.value.trim()||p.id===search.value.trim());if(match){if(tab.value==='count'){counts.value[match.id]=(counts.value[match.id]??0)+1}else add(match);search.value=''}else notice.value=tr('Barcode belum ditemukan pada katalog perangkat.','Barcode not found in the device catalog.')}
function beginCheckout(){if(!view.value.shift){openShift(true);return}if(!cart.value.length)return;error.value='';cash.value=String(total.value/10**scale.value);checkout.value=true;operationId.value ||= `desk-${crypto.randomUUID()}`}
async function saveSale(){if(saving.value||!cashValid.value)return;saving.value=true;error.value='';try{const id=operationId.value||`desk-${crypto.randomUUID()}`;operationId.value=id;update(await invoke<Workspace>('commit',{id,kind:'sale',lines:cart.value.map(l=>({...l})),tendered:cashAtomic.value,expectedTotal:total.value,expectedRevision:view.value.snapshot?.catalog_revision??'',table:tableNumber.value,order:orderNumber.value}));selectedReceipt.value=view.value.operations.find(o=>o.operation.operation_id===id)??null;cart.value=[];operationId.value='';checkout.value=false;notice.value=tr('Transaksi tersimpan di perangkat.','Transaction saved on this device.');if(view.value.settings.auto_print)await print(id,false);for(const j of view.value.kitchen_jobs.filter(j=>j.operation_id===id&&j.state==='queued'))if(view.value.kitchen_printers[j.kitchen_id]?.auto_print){try{update(await invoke<Workspace>('print_kitchen',{id:j.id,duplicate:false}))}catch(e){fail(e)}}tableNumber.value='';orderNumber.value='';void sync(false)}catch(e){fail(e)}finally{saving.value=false}}
async function saveCount(){const lines=Object.entries(counts.value).filter(([,n])=>Number.isInteger(n)&&n>=0).map(([product_id,quantity])=>({product_id,quantity}));if(!lines.length||saving.value)return;saving.value=true;error.value='';operationId.value ||= `desk-${crypto.randomUUID()}`;try{update(await invoke<Workspace>('commit',{id:operationId.value,kind:'count',lines,tendered:0,expectedTotal:0,expectedRevision:view.value.snapshot?.catalog_revision??'',table:tableNumber.value,order:orderNumber.value}));counts.value={};operationId.value='';notice.value=tr('Hasil hitung tersimpan. Setelah sinkronisasi, admin dapat meninjau hasilnya di web.','Count saved. After synchronization, an administrator can review it on the web.');void sync(false)}catch(e){fail(e)}finally{saving.value=false}}
const retryableSync = computed(()=>view.value.operations.filter(o=>o.state==='rejected'&&['POS_INVALID_OPERATION','POS_SHIFT_OPEN_NOT_SYNCED'].includes(String(o.result?.code))).length);
async function retryInvalidSync(){if(syncing.value||saving.value)return;try{update(await invoke<Workspace>('retry_invalid_sync'));await sync(true)}catch(e){fail(e)}}
async function sync(refresh=false){
 if(syncing.value||!view.value.snapshot||!security.value.signed_in||installing.value)return;
 syncing.value=true;const previous=view.value.pending;let madeProgress=false;
 try{update(await invoke<Workspace>('synchronize',{refresh}));online.value=true;lastSync.value=Date.now();failureCount.value=0;madeProgress=view.value.pending<previous;if(error.value===lastSyncError)error.value='';lastSyncError=''}
 catch(e){const reason=String(e);online.value=!['POS_NETWORK_UNAVAILABLE','POS_NETWORK_RESPONSE_INTERRUPTED'].includes(reason);failureCount.value++;if(online.value||refresh){lastSyncError=reason;fail(e)}try{await pollSecurity();update(await invoke<Workspace>('workspace'))}catch{/* Durable data stays in its cashier profile. */}}
 finally{syncing.value=false;scheduleSync(madeProgress&&view.value.pending>0?250:undefined)}
}
function scheduleSync(delay?:number){if(timer)clearTimeout(timer);if(!security.value.signed_in||installing.value)return;timer=setTimeout(()=>{void sync(false)},delay??Math.min(120000,15000*2**Math.min(failureCount.value,3)))}
function connectionRestored(){failureCount.value=0;void sync(true);void checkUpdate(false)}
function parseCash(raw:string){if(!new RegExp(`^\\d+(?:[.,]\\d{1,${Math.max(1,scale.value)}})?$`).test(raw)||(scale.value===0&&/[.,]/.test(raw)))return -1;const [whole,fraction='']=raw.replace(',','.').split('.');const amount=Number(whole)*10**scale.value+Number(fraction.padEnd(scale.value,'0'));return Number.isSafeInteger(amount)?amount:-1}
function openShift(opening:boolean){if(!shiftReady.value){tab.value='shifts';return}if(!opening&&cart.value.length){fail('POS_FINISH_CURRENT_ORDER');return}shiftOpening.value=opening;shiftCash.value='';shiftNote.value='';shiftOperation.value=`desk-${crypto.randomUUID()}`;shiftDialog.value=true;error.value=''}
async function saveShift(){if(saving.value||parseCash(shiftCash.value)<0)return;saving.value=true;try{const id=shiftOperation.value;update(await invoke<Workspace>('shift_event',{id,opening:shiftOpening.value,cash:parseCash(shiftCash.value),note:shiftNote.value}));shiftDialog.value=false;if(!shiftOpening.value)selectedReceipt.value=view.value.operations.find(o=>o.operation.operation_id===id)??null;else tab.value='sale';void sync(false)}catch(e){fail(e)}finally{saving.value=false}}
async function pollSecurity(){try{const state=await invoke<Security>('security_status');security.value=state;showConnect.value=!state.signed_in;if(state.locked){checkout.value=false;selectedReceipt.value=null;shiftDialog.value=false;update(await invoke<Workspace>('workspace'));}}catch(e){fail(e)}}
async function pair(){if(connecting.value)return;connecting.value=true;error.value='';try{update(await invoke<Workspace>('login',{login:email.value,password:password.value,totp:totp.value}));password.value='';totp.value='';await pollSecurity();online.value=!security.value.offline;printer.value={...view.value.settings};showConnect.value=false;tab.value='dashboard';cart.value=[];counts.value={};if(!view.value.shift&&shiftReady.value)openShift(true);void sync(false);void checkUpdate(false)}catch(e){fail(e)}finally{connecting.value=false}}
async function lock(logout=false){try{update(await invoke<Workspace>('lock_pos',{logout}));await pollSecurity();pin.value='';error.value='';if(logout){cart.value=[];counts.value={};operationId.value='';shiftOperation.value='';email.value='';password.value='';totp.value='';checkout.value=false;shiftDialog.value=false;selectedReceipt.value=null;if(timer)clearTimeout(timer)}}catch(e){fail(e)}}
async function unlock(){if(connecting.value)return;connecting.value=true;error.value='';try{update(await invoke<Workspace>('unlock_pos',{pin:pin.value}));pin.value='';await pollSecurity();if(!view.value.shift&&shiftReady.value)openShift(true);void sync(false)}catch(e){fail(e)}finally{connecting.value=false}}
function activity(){if(!security.value.signed_in||security.value.locked||Date.now()-lastActivity<10000)return;lastActivity=Date.now();void invoke('activity').catch(()=>pollSecurity())}
async function checkUpdate(manual=true){if(checkingUpdate.value)return;checkingUpdate.value=true;try{patch.value=await invoke<UpdateInfo>('check_update');if(manual)notice.value=patch.value.available?tr('Versi baru tersedia. Buka menu Pembaruan.','A new version is available. Open Updates.'):tr('Anda sudah menggunakan versi terbaru.','You are using the latest version.')}catch(e){if(manual)fail(e)}finally{checkingUpdate.value=false}}
async function installUpdate(){if(installing.value||!patch.value?.version)return;if(cart.value.length){fail('POS_FINISH_CURRENT_ORDER');return}installing.value=true;updateStage.value='check';updateBytes.value=0;updateTotal.value=0;try{await invoke('install_update',{version:patch.value.version})}catch(e){fail(e)}finally{installing.value=false;scheduleSync()}}
function logoUrl(logo?:Logo|null){if(!logo)return '';const canvas=document.createElement('canvas');canvas.width=logo.width;canvas.height=logo.height;const ctx=canvas.getContext('2d')!;const raw=atob(logo.bits);const data=ctx.createImageData(logo.width,logo.height);for(let i=0;i<logo.width*logo.height;i++){const color=(raw.charCodeAt(Math.floor(i/8))&(128>>(i%8)))?0:255;data.data.set([color,color,color,255],i*4)}ctx.putImageData(data,0,0);return canvas.toDataURL('image/png')}
async function savePrinter(){try{update(await invoke<Workspace>('save_printer',{settings:printer.value}));notice.value=tr('Pengaturan perangkat tersimpan.','Device settings saved.');return true}catch(e){fail(e);return false}}
async function print(id:string,duplicate:boolean){try{await invoke('print_receipt',{id,duplicate});notice.value=tr('Struk dikirim ke printer. Periksa hasil cetaknya.','Receipt sent to the printer. Check the printed output.')}catch(e){fail(e)}}
async function testPrinter(drawer=false){try{if(!await savePrinter())return;await invoke('test_printer',{drawer});notice.value=tr('Perintah uji dikirim. Periksa perangkat.','Test sent. Check your device.')}catch(e){fail(e)}}
async function reloadPrinters(){try{queues.value=await invoke<string[]>('printers')}catch(e){fail(e)}}
function stateLabel(state:string){return ({pending:tr('Menunggu sinkron','Waiting to sync'),accepted:tr('Tersinkron','Synced'),conflict:tr('Perlu ditinjau','Needs review'),rejected:tr('Perlu diperbaiki','Needs attention'),review:tr('Menunggu tinjauan','Awaiting review')} as Record<string,string>)[state]??state}
onMounted(async()=>{try{appVersion.value=await invoke<string>('app_version');await pollSecurity();void reloadPrinters();void checkUpdate(false);try{unlistenUpdate=await listen<{stage:string;downloaded?:number;total?:number}>('pos-update-progress',event=>{updateStage.value=event.payload.stage;updateBytes.value=event.payload.downloaded??0;updateTotal.value=event.payload.total??0})}catch{/* Native checks remain mandatory. */}}catch(e){fail(e)}clock=setInterval(()=>{now.value=Date.now()},1000);securityTimer=setInterval(()=>void pollSecurity(),5000);updateTimer=setInterval(()=>void checkUpdate(false),6*60*60*1000);window.addEventListener('online',connectionRestored);window.addEventListener('pointerdown',activity);window.addEventListener('keydown',activity)})
onUnmounted(()=>{unlistenUpdate?.();window.removeEventListener('online',connectionRestored);if(timer)clearTimeout(timer);if(clock)clearInterval(clock);if(securityTimer)clearInterval(securityTimer);if(updateTimer)clearInterval(updateTimer);window.removeEventListener('pointerdown',activity);window.removeEventListener('keydown',activity)})
</script>

<template>
<div class="app-shell" :class="{'sign-in-mode':showConnect}">
 <aside class="rail" :inert="blocked"><a class="brand" href="#" @click.prevent="tab='sale'">one<span>Qay</span><small>POINT OF SALE</small></a><nav><button v-for="item in nav" :key="item.id" :class="{active:tab===item.id}" @click="tab=item.id;search='';category=''" :aria-current="tab===item.id?'page':undefined"><Icon :name="item.icon"/><span>{{item.label}}</span><b v-if="item.badge">{{item.badge}}</b></button></nav><div class="rail-bottom"><div class="local-safe"><Icon name="shield-check"/><div><strong>{{tr('Tersimpan lokal','Locally stored')}}</strong><small>SQLite · {{tr('Perangkat ini','This device')}}</small></div></div><button class="profile" @click="lock(true)"><span class="avatar">K</span><span><strong>{{view.snapshot?.cashier_name||tr('Kasir Windows','Windows cashier')}}</strong><small>{{tr('Ganti kasir','Switch cashier')}}</small></span><Icon name="chevron-right" :size="16"/></button><p>© {{new Date().getFullYear()}} oneQay</p></div></aside>
 <div class="workspace" :inert="blocked"><header class="topbar"><div><div class="breadcrumb">{{tr('Ruang kerja','Workspace')}} <Icon name="chevron-right" :size="13"/> {{nav.find(n=>n.id===tab)?.label}}</div><h1>{{tab==='sale'?tr('Selamat berjualan.','Ready for a good day.'):nav.find(n=>n.id===tab)?.label}}</h1></div><div class="header-actions"><button class="shift-action" @click="openShift(!view.shift)"><Icon name="wallet" :size="17"/>{{view.shift?tr('Tutup kas','Close cash'):tr('Buka kas','Open cash')}}</button><button class="icon-button" @click="lock()" :aria-label="tr('Kunci POS','Lock POS')"><Icon name="shield-check"/></button><button class="connection" :class="online?'connected':'disconnected'" @click="sync(true)"><span class="status-dot" :class="{pulse:syncing}"/>{{syncing?tr('Menyinkronkan','Syncing'):online?'Online':'Offline'}}<Icon name="refresh-cw" :size="14" :class="{spin:syncing}"/></button><button class="language" @click="changeLanguage" aria-label="Change language"><Icon name="globe" :size="17"/>{{language==='id'?'ID':'ENG'}}</button><span class="date">{{new Date(now).toLocaleDateString(language==='id'?'id-ID':'en-GB',{day:'numeric',month:'short',year:'numeric'})}}</span></div></header>
 <div v-if="error" class="feedback danger" role="alert"><Icon name="circle-alert"/><div><strong>{{humanError(error)}}</strong><code>{{error}}</code><button v-if="needsLogin" class="text-button" @click="showConnect=true">{{tr('Hubungkan ulang','Reconnect')}}</button></div><button class="icon-button" @click="error=''" aria-label="Dismiss"><Icon name="x" :size="16"/></button></div>
 <div v-if="tab==='sync'&&retryableSync" class="feedback" role="status"><Icon name="refresh-cw"/><div><strong>{{tr('Antrean lama dapat dikirim ulang dengan referensi yang sama.','Old queue entries can be retried with the same references.')}}</strong><p>{{tr('Struk lokal tetap disimpan. Server memeriksa shift, harga, stok, izin dan bukti sebelumnya; transaksi yang sudah diterima tidak dibuat ulang.','Local receipts are preserved. The server checks shift, price, stock, permissions and prior receipts; accepted transactions are not duplicated.')}}</p><button class="primary" :disabled="syncing||saving" @click="retryInvalidSync">{{tr('Pulihkan & sinkronkan antrean','Recover & synchronize queue')}} ({{retryableSync}})</button></div></div>
 <div v-if="notice" class="feedback success" role="status"><Icon name="circle-check"/><span>{{notice}}</span><button class="icon-button" @click="notice=''" aria-label="Dismiss"><Icon name="x" :size="16"/></button></div>
 <div v-if="!online&&view.snapshot&&!error" class="offline-banner"><Icon name="database" :size="18"/><span>{{tr('Koneksi terputus? Kasir tetap berjalan. Transaksi disimpan di perangkat dan dikirim saat tersambung kembali.','No connection? Keep selling. Transactions are stored on this device and sent when the connection returns.')}}</span><b>{{view.pending}} {{tr('menunggu','pending')}}</b></div>
 <div v-if="leaseExpired&&view.snapshot" class="feedback warning"><Icon name="clock-3"/><span>{{tr('Izin offline perlu diperbarui. Sambungkan internet sebelum membuat transaksi baru.','Offline authorization needs refreshing. Connect before starting a new transaction.')}}</span><button class="text-button" @click="sync(true)">{{tr('Perbarui','Refresh')}}</button></div>
 <section v-if="!shiftReady&&!showConnect&&!security.locked" class="shift-recovery" role="status"><Icon name="wallet"/><div><strong>{{tr('Login berhasil. Ada shift yang perlu dilanjutkan.','Signed in. A shift needs attention.')}}</strong><p>{{view.shift_status==='other_cashier'?tr('Register ini masih digunakan kasir lain. Anda dapat berganti akun untuk melanjutkan shift tersebut.','This register is in use by another cashier. Switch to that account to continue its shift.'):view.shift_status==='closing'?tr('Kas sudah ditutup di perangkat. Pemilik bisnis dapat mengesahkan laporan melalui web → POS Windows → Shift & keamanan. Setelah disahkan, shift berikutnya dapat dibuka.','Cash has been closed locally. Your business owner can finalize the report on the web → Windows POS → Shifts & security. You can then open the next shift.'):tr('Riwayat shift di perangkat dan server perlu diperiksa pemilik bisnis. Sinkronisasi dan pembaruan tetap tersedia, dan transaksi lama tetap tersimpan.','The business owner needs to review the device and server shift history. Sync and updates remain available, and existing transactions stay saved.')}}</p><button class="secondary" :disabled="syncing" @click="sync(true)">{{tr('Periksa lagi','Check again')}}</button><button class="secondary" @click="lock(true)">{{tr('Ganti akun','Switch account')}}</button></div></section><EnterprisePanels :app-version="appVersion" :checking-update="checkingUpdate" v-if="['dashboard','shifts','kitchens','updates'].includes(tab)" :tab="tab" :view="view" :language="language" :queues="queues" :money="money" :patch="patch" @update="update" @error="fail" @receipt="selectedReceipt=$event" @shift="openShift" @check="checkUpdate()" @install="installUpdate"/>
 <main v-else-if="tab==='sale'" class="checkout-layout">
  <section class="catalog"><div class="summary-strip"><div><span class="summary-icon violet"><Icon name="wallet"/></span><div><small>{{tr('Penjualan lokal hari ini','Local sales today')}}</small><strong>{{money(salesToday)}}</strong></div></div><div><span class="summary-icon mint"><Icon name="receipt-text"/></span><div><small>{{tr('Transaksi','Transactions')}}</small><strong>{{view.metrics.count??0}} <em>{{tr('struk','receipts')}}</em></strong></div></div><div><span class="summary-icon amber"><Icon name="refresh-cw"/></span><div><small>{{tr('Antrean sinkronisasi','Sync queue')}}</small><strong>{{view.pending}} <em>{{tr('transaksi','transactions')}}</em></strong></div></div></div>
  <div class="catalog-heading"><div><h2>{{tr('Pilih produk','Choose products')}}</h2><p>{{tr('Pindai barcode atau cari produk untuk mulai.','Scan a barcode or find a product to get started.')}}</p></div><span class="count-tag">{{view.products.length}} {{tr('produk','products')}}</span></div>
  <div class="search-box"><Icon name="search"/><input ref="barcodeInput" v-model="search" :placeholder="tr('Cari nama produk atau pindai barcode…','Search products or scan a barcode…')" @keydown.enter.prevent="scan" autocomplete="off"/><kbd>ENTER</kbd><Icon name="scan-line"/></div>
  <div class="categories"><button :class="{selected:!category}" @click="category=''">{{tr('Semua produk','All products')}}</button><button v-for="c in categories" :key="c" :class="{selected:category===c}" @click="category=c">{{c}}</button></div>
  <div class="product-grid"><button v-for="(p,index) in products" :key="p.id" class="product-card" @click="add(p)" :disabled="(p.tracks_stock!==false&&p.stock===0)||saving"><div class="product-art" :class="`tint-${index%5}`"><Icon :name="index%3===0?'package':index%3===1?'boxes':'store'" :size="40"/><span class="product-add"><Icon name="plus" :size="17"/></span></div><div class="product-copy"><small>{{p.category||tr('Produk','Product')}}</small><h3>{{p.name}}</h3><div><strong>{{money(p.price)}}</strong><span :class="{'low-stock':p.tracks_stock!==false&&p.stock<5}">{{p.tracks_stock===false?tr('∞ Unlimited','∞ Unlimited'):p.stock+' '+tr('stok','left')}}</span></div></div></button></div>
  <div v-if="!products.length" class="empty"><span class="empty-icon"><Icon name="package" :size="38"/></span><h3>{{tr('Rak ini masih kosong.','This shelf is waiting.')}}</h3><p>{{tr('Hubungkan akun dan siapkan katalog bisnis Anda melalui web.','Connect your account and prepare the business catalog on the web.')}}</p><button class="secondary" @click="showConnect=true">{{tr('Hubungkan perangkat','Connect device')}}</button></div>
  <div class="catalog-foot"><Icon name="shield-check" :size="15"/>{{tr('Harga dan mata uang mengikuti pengaturan bisnis.','Prices and currency follow business settings.')}}</div></section>
  <aside class="cart-panel"><div class="cart-title"><div><span class="eyebrow">{{tr('TRANSAKSI BARU','NEW TRANSACTION')}}</span><h2>{{tr('Keranjang belanja','Current order')}} <span>{{quantity}}</span></h2></div><Icon name="shopping-cart" :size="25"/></div><div class="cart-context"><Icon name="store" :size="16"/>{{view.snapshot?.business_name||'oneQay POS'}}<span class="cash-pill">{{tr('Tunai','Cash')}}</span></div><div class="order-fields"><label>{{tr('Nomor meja','Table')}}<input v-model="tableNumber" maxlength="24" placeholder="04" :disabled="saving"/></label><label>{{tr('Nomor order','Order number')}}<input v-model="orderNumber" maxlength="32" placeholder="A-012" :disabled="saving"/></label></div><div class="cart-list"><div v-for="l in cartLines" :key="l.product_id" class="cart-item"><div class="cart-thumbnail"><Icon name="package" :size="22"/></div><div class="cart-item-info"><strong>{{l.product.name}}</strong><small>{{money(l.product.price)}}</small><div class="stepper"><button @click="adjust(l.product_id,-1)" :disabled="saving" :aria-label="tr('Kurangi','Decrease')"><Icon name="minus" :size="13"/></button><span>{{l.quantity}}</span><button @click="adjust(l.product_id,1)" :disabled="saving" :aria-label="tr('Tambah','Increase')"><Icon name="plus" :size="13"/></button></div></div><strong class="line-total">{{money(l.product.price*l.quantity)}}</strong></div><div v-if="!cart.length" class="empty cart-empty"><Icon name="shopping-cart" :size="46"/><h3>{{tr('Mulai dari satu produk.','Start with one product.')}}</h3><p>{{tr('Produk yang dipilih akan muncul di sini.','Selected products will appear here.')}}</p></div></div><div class="cart-bottom"><div class="subtotal"><span>{{tr('Subtotal','Subtotal')}} · {{quantity}} {{tr('barang','items')}}</span><strong>{{money(total)}}</strong></div><div class="total-row"><span>{{tr('Total pembayaran','Total due')}}</span><strong>{{money(total)}}</strong></div><button class="primary pay" @click="beginCheckout" :disabled="!cart.length||leaseExpired||saving"><Icon name="wallet"/>{{tr('Bayar tunai','Cash payment')}}<Icon name="arrow-right"/></button><p><Icon name="shield-check" :size="13"/>{{tr('Disimpan lokal sebelum sinkronisasi','Saved locally before synchronization')}}</p></div></aside>
 </main>
 <main v-else-if="tab==='history'||tab==='sync'" class="page-content"><div class="page-intro"><div><h2>{{tab==='sync'?tr('Setiap transaksi tetap terlacak.','Every transaction accounted for.'):tr('Riwayat transaksi perangkat','Device transaction history')}}</h2><p>{{tr('Struk lokal tetap tersimpan, termasuk transaksi yang perlu ditinjau.','Local receipts are retained, including transactions that need review.')}}</p></div><button class="primary compact" @click="sync(true)" :disabled="syncing"><Icon name="refresh-cw" :class="{spin:syncing}"/>{{tr('Sinkronkan sekarang','Sync now')}}</button></div><div v-if="tab==='sync'" class="sync-cards"><article><Icon name="clock-3"/><strong>{{view.pending}}</strong><span>{{tr('Menunggu server','Waiting for server')}}</span></article><article><Icon name="circle-alert"/><strong>{{view.review}}</strong><span>{{tr('Perlu tinjauan','Need review')}}</span></article><article><Icon name="activity"/><strong>{{online?'Online':'Offline'}}</strong><span>{{lastSync?new Date(lastSync).toLocaleTimeString():tr('Belum tersambung','Not connected yet')}}</span></article></div><div class="table-card"><table><thead><tr><th>{{tr('Waktu','Time')}}</th><th>{{tr('Referensi lokal','Local reference')}}</th><th>{{tr('Jenis','Type')}}</th><th>{{tr('Total','Total')}}</th><th>Status</th><th></th></tr></thead><tbody><tr v-for="o in view.operations.filter(o=>tab!=='sync'||o.state!=='accepted')" :key="o.operation.operation_id"><td>{{new Date(o.operation.created_at*1000).toLocaleString(language==='id'?'id-ID':'en-GB',{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'})}}</td><td class="reference">{{o.operation.operation_id.slice(-12)}}<small v-if="o.result?.sale_id">{{o.result.sale_id}}</small></td><td>{{o.operation.kind==='sale'?tr('Penjualan','Sale'):tr('Opname','Stock count')}}</td><td><strong>{{o.operation.kind==='sale'?money(o.total):'—'}}</strong></td><td><span class="status-chip" :class="o.state">{{stateLabel(o.state)}}</span><small v-if="o.result?.code&&o.state!=='accepted'">{{o.result.code}}</small></td><td><button class="icon-button" @click="selectedReceipt=o" :aria-label="tr('Lihat struk','View receipt')"><Icon name="arrow-up-right"/></button></td></tr></tbody></table><div v-if="!view.operations.length" class="empty"><Icon name="receipt-text" :size="38"/><h3>{{tr('Belum ada transaksi.','No transactions yet.')}}</h3><p>{{tr('Transaksi pertama Anda akan muncul di sini.','Your first transaction will appear here.')}}</p></div></div><div class="help-note"><Icon name="circle-alert"/><p>{{tr('Jika harga, stok, atau shift berubah di server, transaksi ditandai untuk ditinjau. Data tidak dihapus dan stok server tidak ditimpa. Sampaikan kode kendala dan referensi kepada admin.','If prices, stock, or shifts change on the server, transactions are flagged for review. Data is retained and server inventory is never overwritten. Share the code and reference with your administrator.')}}</p></div></main>
 <main v-else-if="tab==='count'" class="page-content"><div class="page-intro"><div><h2>{{tr('Hitung stok, pindai lebih cepat.','Count stock. Scan faster.')}}</h2><p>{{tr('Scanner USB atau Bluetooth dengan mode keyboard dapat langsung digunakan.','USB or Bluetooth scanners in keyboard mode work directly.')}}</p></div><button class="primary compact" :disabled="saving||!Object.keys(counts).length||leaseExpired" @click="saveCount"><Icon name="circle-check"/>{{tr('Simpan hasil hitung','Save stock count')}}</button></div><div class="search-box"><Icon name="scan-line"/><input v-model="search" :placeholder="tr('Pindai barcode, lalu tekan Enter','Scan a barcode and press Enter')" @keydown.enter.prevent="scan"/><kbd>ENTER</kbd></div><div class="table-card"><table><thead><tr><th>{{tr('Produk','Product')}}</th><th>Barcode</th><th>{{tr('Stok perangkat','Device stock')}}</th><th>{{tr('Hasil hitung','Counted')}}</th></tr></thead><tbody><tr v-for="p in products" :key="p.id"><td><strong>{{p.name}}</strong></td><td class="reference">{{p.barcode||'—'}}</td><td>{{p.stock}}</td><td><input class="count-input" v-model.number="counts[p.id]" type="number" min="0" max="1000000" step="1" inputmode="numeric" placeholder="0" @input="operationId=''"/></td></tr></tbody></table></div><div class="help-note"><Icon name="clipboard-list"/><p>{{tr('Hasil opname dikirim sebagai usulan hitung untuk ditinjau admin. Penghitungan tidak langsung mengubah stok jual. Akun harus memiliki izin inventori saat sinkronisasi.','Counts are submitted for administrator review. Counting does not directly change sellable stock. Inventory permission is required when synchronizing.')}}</p></div></main>
 <main v-else class="page-content"><div class="page-intro"><div><h2>{{tr('Ruang kerja yang siap melayani.','A checkout ready to serve.')}}</h2><p>{{tr('Atur printer struk, laci kas, dan scanner untuk perangkat ini.','Set up the receipt printer, cash drawer, and scanner on this device.')}}</p></div></div><div class="settings-grid"><section class="settings-card"><div class="section-icon"><Icon name="printer"/></div><h3>{{tr('Printer struk','Receipt printer')}}</h3><p>{{tr('Printer ESC/POS 58 mm atau 80 mm.','58 mm or 80 mm ESC/POS printer.')}}</p><label>{{tr('Jenis sambungan','Connection type')}}<select v-model="printer.transport"><option value="windows">USB / Bluetooth · Windows printer</option><option value="network">LAN / WLAN · TCP/IP</option></select></label><template v-if="printer.transport==='windows'"><label>{{tr('Antrean printer Windows','Windows printer queue')}}<select v-model="printer.queue"><option value="">{{tr('Pilih printer','Choose a printer')}}</option><option v-for="q in queues" :key="q">{{q}}</option></select></label><button class="text-button" @click="reloadPrinters"><Icon name="refresh-cw" :size="14"/>{{tr('Muat ulang daftar','Refresh list')}}</button><p class="field-help">{{tr('Pasang driver USB atau pasangkan printer Bluetooth pada Windows terlebih dahulu. Pilih antrean yang mendukung RAW ESC/POS.','Install the USB driver or pair the Bluetooth printer in Windows first. Select a queue that supports RAW ESC/POS.')}}</p></template><div v-else class="field-row"><label>{{tr('Alamat IP / host','IP address / host')}}<input v-model="printer.host" placeholder="192.168.1.100"/></label><label>Port<input v-model.number="printer.port" type="number" min="1" max="65535" inputmode="numeric"/></label></div><label>{{tr('Lebar kertas','Paper width')}}<select v-model.number="printer.paper_mm"><option :value="80">80 mm</option><option :value="58">58 mm</option></select></label><label class="check-label"><input v-model="printer.auto_print" type="checkbox"/>{{tr('Cetak otomatis setelah pembayaran','Print automatically after payment')}}</label><div class="button-row"><button class="primary compact" @click="savePrinter"><Icon name="check"/>{{tr('Simpan pengaturan','Save settings')}}</button><button class="secondary" @click="testPrinter(false)">{{tr('Uji cetak','Test print')}}</button></div></section><div class="settings-stack"><section class="settings-card"><div class="section-icon mint"><Icon name="wallet"/></div><h3>{{tr('Laci kas','Cash drawer')}}</h3><p>{{tr('Hubungkan laci RJ11/RJ12 ke printer yang mendukung pulsa ESC/POS.','Connect an RJ11/RJ12 drawer to a printer supporting an ESC/POS pulse.')}}</p><label class="check-label"><input v-model="printer.drawer_enabled" type="checkbox"/>{{tr('Buka laci saat struk tunai pertama dicetak','Open drawer on the first cash receipt print')}}</label><button class="secondary" :disabled="!printer.drawer_enabled" @click="testPrinter(true)">{{tr('Uji buka laci kas','Test opening cash drawer')}}</button></section><section class="settings-card"><div class="section-icon amber"><Icon name="scan-line"/></div><h3>{{tr('Scanner barcode','Barcode scanner')}}</h3><p>{{tr('Gunakan mode USB HID / keyboard atau Bluetooth HID. Atur akhiran pemindaian menjadi Enter, lalu arahkan kursor ke kolom pencarian atau opname.','Use USB HID / keyboard or Bluetooth HID mode. Set the scan suffix to Enter and focus the search or stock count field.')}}</p><span class="status-chip accepted">{{tr('Tidak memerlukan driver tambahan di aplikasi','No additional application driver needed')}}</span></section></div></div></main>
 </div>
 <section v-if="showConnect" class="login-screen"><aside class="login-story"><a class="login-brand">one<span>Qay</span><small>POINT OF SALE</small></a><div class="story-content"><span class="story-badge"><Icon name="monitor" :size="16"/> WINDOWS POS</span><h1>{{tr('Siap melayani.','Ready to serve.')}}<br/><span>{{tr('Di setiap transaksi.','At every checkout.')}}</span></h1><p>{{tr('Ruang kerja kasir yang rapi, cepat, dan tetap berjalan saat koneksi terputus.','A clear, fast checkout workspace that keeps working when the connection drops.')}}</p><div class="story-terminal"><div><Icon name="store"/><span>oneQay POS</span><i/></div><section><span>{{tr('Setiap pesanan, tercatat.','Every order, accounted for.')}}</span><strong>Rp 248.000</strong><div class="terminal-bars"><b/><b/><b/><b/><b/><b/><b/></div><footer><Icon name="circle-check" :size="17"/>{{tr('Tersimpan di perangkat','Saved on your device')}}</footer></section></div><div class="story-trust"><span><Icon name="database" :size="17"/>{{tr('Siap offline','Offline ready')}}</span><span><Icon name="shield-check" :size="17"/>{{tr('Akun terlindungi','Protected accounts')}}</span></div></div><footer>© {{new Date().getFullYear()}} oneQay</footer></aside><main class="login-main"><button class="language login-language" @click="changeLanguage"><Icon name="globe" :size="17"/>{{language==='id'?'ID':'ENG'}}</button><form class="login-form" @submit.prevent="pair"><span class="login-mark"><Icon name="shopping-cart" :size="30"/></span><span class="eyebrow">{{tr('RUANG KERJA KASIR','CASHIER WORKSPACE')}}</span><h2>{{tr('Selamat datang kembali.','Welcome back.')}}</h2><p>{{tr('Masuk dengan akun petugas yang dibuat oleh pemilik bisnis Anda.','Sign in with the cashier account created by your business owner.')}}</p><div v-if="error" class="inline-error" role="alert">{{humanError(error)}}<code>{{error}}</code></div><label>{{tr('Email kasir','Cashier email')}}<input v-model="email" required type="email" maxlength="190" autocomplete="username" placeholder="kasir@bisnis.com" :disabled="connecting"/></label><label>Password<input v-model="password" required type="password" maxlength="72" autocomplete="current-password" :placeholder="tr('Masukkan password','Enter your password')" :disabled="connecting"/></label><details class="login-mfa"><summary>{{tr('Akun menggunakan autentikator?','Does your account use an authenticator?')}}</summary><label>{{tr('Kode autentikator','Authenticator code')}}<input v-model="totp" inputmode="numeric" pattern="[0-9]{6}" maxlength="6" autocomplete="one-time-code"/></label></details><button class="primary pay" :disabled="connecting"><span>{{connecting?tr('Memeriksa akun…','Checking account…'):tr('Masuk ke kasir','Sign in to checkout')}}</span><Icon :name="connecting?'refresh-cw':'arrow-right'" :class="{spin:connecting}"/></button><div class="login-offline"><Icon name="shield-check"/><p>{{tr('Login pertama memerlukan internet. Akun yang sudah diverifikasi dapat masuk kembali saat offline selama izin perangkat masih berlaku.','First sign-in requires internet. Verified accounts can sign in offline while the device authorization remains valid.')}}</p></div></form><div class="login-update"><button class="secondary" :disabled="checkingUpdate||connecting||installing" @click="checkUpdate(true)"><Icon name="refresh-cw" :class="{spin:checkingUpdate}"/>{{tr('Periksa pembaruan','Check for updates')}}</button><button v-if="patch?.available" class="primary" :disabled="connecting||installing" @click="installUpdate">{{tr('Pasang versi','Install version')}} {{patch.version}}</button><p v-if="notice" role="status">{{notice}}</p></div><footer>oneQay POS <b>v{{appVersion}}</b> · Windows 10+</footer></main></section>
 <div v-if="!showConnect&&security.locked" class="modal-backdrop lock-backdrop"><form class="modal lock-modal" @submit.prevent="unlock"><span class="login-mark"><Icon name="shield-check" :size="32"/></span><h2>{{tr('Kasir sedang dikunci.','Checkout is locked.')}}</h2><p>{{security.login}}</p><label>{{tr('Masukkan PIN 6 angka','Enter your 6-digit PIN')}}<input v-model="pin" type="password" inputmode="numeric" pattern="[0-9]{6}" minlength="6" maxlength="6" required autocomplete="off" class="pin-input"/></label><div v-if="error" class="inline-error" role="alert">{{humanError(error)}}<code>{{error}}</code></div><button class="primary pay" :disabled="connecting">{{tr('Buka kunci','Unlock')}}</button><button type="button" class="secondary" @click="lock(true)">{{tr('Gunakan akun lain','Use another account')}}</button><p class="secure-caption">{{tr('PIN dikelola oleh pemilik bisnis melalui web.','Your business owner manages the PIN on the web.')}}</p></form></div>
 <div v-if="shiftDialog&&!security.locked&&!showConnect" class="modal-backdrop"><form class="modal shift-modal" @submit.prevent="saveShift"><button v-if="view.shift||!shiftOpening" type="button" class="modal-close icon-button" :disabled="saving" @click="shiftDialog=false"><Icon name="x"/></button><span class="login-mark"><Icon name="wallet" :size="30"/></span><span class="eyebrow">{{shiftOpening?tr('AWALI SHIFT ANDA','START YOUR SHIFT'):tr('SELESAIKAN SHIFT','COMPLETE YOUR SHIFT')}}</span><h2>{{shiftOpening?tr('Berapa kas awal hari ini?','How much cash are you starting with?'):tr('Saatnya menghitung kas.','Time to count your cash.')}}</h2><p>{{view.snapshot?.cashier_name}} · {{view.snapshot?.business_name}}</p><div v-if="error" class="inline-error" role="alert">{{humanError(error)}}<code>{{error}}</code></div><label>{{shiftOpening?tr('Kas pembukaan','Opening cash'):tr('Kas fisik yang dihitung','Physical cash counted')}}<input v-model="shiftCash" required inputmode="decimal" type="text" class="cash-input" :disabled="saving" placeholder="0"/></label><label v-if="!shiftOpening">{{tr('Catatan penutupan / penjelasan selisih','Closing note / variance explanation')}}<input v-model="shiftNote" maxlength="500" :disabled="saving"/></label><button class="primary pay" :disabled="saving||parseCash(shiftCash)<0"><Icon name="circle-check"/>{{shiftOpening?tr('Buka kas & mulai melayani','Open cash & start serving'):tr('Simpan tutup kas & laporan','Save closing cash & report')}}</button><button v-if="shiftOpening" type="button" class="secondary" :disabled="saving" @click="lock(true)">{{tr('Gunakan akun lain','Use another account')}}</button><p class="secure-caption">{{tr('Tersimpan di perangkat terlebih dahulu. Laporan dikirim ke email yang diatur pemilik bisnis setelah sinkronisasi.','Saved on your device first. Reports are emailed to recipients configured by the business owner after synchronization.')}}</p></form></div>
 <div v-if="installing" class="modal-backdrop"><section class="modal lock-modal"><Icon name="refresh-cw" class="spin" :size="40"/><h2>{{tr('Menyiapkan pembaruan…','Preparing your update…')}}</h2><progress v-if="updateStage==='download'&&updateTotal>0" :value="updateBytes" :max="updateTotal"/><p role="status">{{({check:tr('Memeriksa paket…','Checking package…'),download:tr('Mengunduh patch…','Downloading patch…'),verify:tr('Memverifikasi tanda tangan…','Verifying signature…'),backup:tr('Mencadangkan akun dan transaksi…','Backing up accounts and transactions…'),install:tr('Memasang pembaruan…','Installing update…')} as Record<string,string>)[updateStage]}}</p><p>{{tr('Memverifikasi unduhan dan mencadangkan data. Mohon biarkan aplikasi tetap terbuka.','Verifying the download and backing up data. Please keep the app open.')}}</p></section></div>
 <div v-if="checkout" class="modal-backdrop"><section class="modal payment-modal" role="dialog" aria-modal="true" aria-labelledby="payment-title"><button class="modal-close icon-button" @click="!saving&&(checkout=false)" :disabled="saving" aria-label="Close"><Icon name="x"/></button><span class="eyebrow">{{tr('PEMBAYARAN TUNAI','CASH PAYMENT')}}</span><h2 id="payment-title">{{tr('Selesaikan transaksi','Complete the sale')}}</h2><div v-if="error" class="inline-error" role="alert">{{humanError(error)}}<code>{{error}}</code></div><div class="payment-total"><span>{{tr('Total pembayaran','Total due')}}</span><strong>{{money(total)}}</strong><small>{{quantity}} {{tr('barang','items')}}</small></div><label>{{tr('Uang diterima','Cash received')}}<input v-model="cash" type="text" inputmode="decimal" class="cash-input" :disabled="saving"/></label><div class="quick-cash"><button @click="cash=String(total/10**scale)">{{tr('Uang pas','Exact amount')}}</button><button v-for="n in (currency==='IDR'?[50000,100000,200000]:[10,20,50])" :key="n" @click="cash=String(n)">{{money(n*10**scale)}}</button></div><div class="change-row"><span>{{tr('Kembalian','Change')}}</span><strong>{{money(Math.max(0,cashAtomic-total))}}</strong></div><button class="primary pay" @click="saveSale" :disabled="!cashValid||saving"><Icon :name="saving?'refresh-cw':'circle-check'" :class="{spin:saving}"/>{{saving?tr('Menyimpan…','Saving…'):tr('Konfirmasi & simpan','Confirm & save')}}</button><p class="secure-caption">{{tr('Pastikan uang tunai sudah diterima. Struk bersifat lokal sampai server menerima sinkronisasi.','Confirm cash has been received. The receipt remains local until synchronization is accepted.')}}</p></section></div>
 <div v-if="selectedReceipt" class="modal-backdrop"><section class="modal receipt-modal" role="dialog" aria-modal="true" aria-labelledby="receipt-title"><button class="modal-close icon-button" @click="selectedReceipt=null" aria-label="Close"><Icon name="x"/></button><div class="receipt-top"><span class="receipt-check"><Icon name="circle-check" :size="28"/></span><h2 id="receipt-title">{{tr('Transaksi tersimpan','Transaction saved')}}</h2><span class="status-chip" :class="selectedReceipt.state">{{stateLabel(selectedReceipt.state)}}</span></div><div v-if="error" class="inline-error" role="alert">{{humanError(error)}}<code>{{error}}</code></div><div class="receipt-paper"><img v-if="selectedReceipt.operation.kind==='sale'&&selectedReceipt.receipt.logo" class="receipt-logo" :src="logoUrl(selectedReceipt.receipt.logo)" alt="Logo"/><strong class="receipt-brand">{{selectedReceipt.receipt.business||'oneQay'}}</strong><span>{{selectedReceipt.receipt.cashier}}</span><span v-if="selectedReceipt.receipt.table||selectedReceipt.receipt.order">{{tr('Meja','Table')}} {{selectedReceipt.receipt.table||'—'}} · {{tr('Order','Order')}} {{selectedReceipt.receipt.order||'—'}}</span><span>{{new Date(selectedReceipt.operation.created_at*1000).toLocaleString()}}</span><p v-if="selectedReceipt.state!=='accepted'">{{tr('STRUK LOKAL · BELUM FINAL DI SERVER','LOCAL RECEIPT · NOT FINAL ON SERVER')}}</p><template v-if="selectedReceipt.operation.kind!=='shift_close'"><div v-for="l in selectedReceipt.receipt.lines" :key="l.name" class="receipt-line"><span>{{l.name}} × {{l.quantity}}</span><strong>{{money(l.price*l.quantity)}}</strong></div><div class="receipt-line receipt-total"><strong>Total</strong><strong>{{money(selectedReceipt.total)}}</strong></div><div class="receipt-line"><span>{{tr('Tunai','Cash')}}</span><span>{{money(selectedReceipt.receipt.tendered)}}</span></div><div class="receipt-line"><span>{{tr('Kembalian','Change')}}</span><span>{{money(selectedReceipt.receipt.change)}}</span></div><p class="receipt-footer">{{selectedReceipt.receipt.footer}}</p></template><template v-else><h3>{{tr('Laporan tutup kas','Cash closure report')}}</h3><div v-for="(label,key) in {opening:tr('Kas awal','Opening cash'),sales:tr('Penjualan lokal','Local sales'),expected:tr('Kas seharusnya','Expected cash'),counted:tr('Kas dihitung','Counted cash'),variance:tr('Selisih','Variance')}" :key="key" class="receipt-line"><span>{{label}}</span><strong>{{money(selectedReceipt.receipt[key]??0)}}</strong></div><p>{{selectedReceipt.receipt.note}}</p><p v-if="selectedReceipt.result?.mail_queued">{{selectedReceipt.result.mail_queued}} {{tr('laporan masuk antrean email','reports queued for email')}}</p></template><code>{{selectedReceipt.operation.operation_id}}</code><code v-if="selectedReceipt.result">{{selectedReceipt.result.code}}<br>{{selectedReceipt.result.correlation_id}}</code></div><div v-if="['sale','shift_close'].includes(selectedReceipt.operation.kind)" class="button-row"><button class="primary compact" @click="print(selectedReceipt.operation.operation_id,false)"><Icon name="printer"/>{{tr('Cetak struk','Print receipt')}}</button><button class="secondary" @click="print(selectedReceipt.operation.operation_id,true)">{{tr('Cetak salinan','Print copy')}}</button></div></section></div>
</div>
</template>

